impl ThreadHistoryBuilder {
fn new() -> Self {
        Self {
            turns: Vec::new(),
            current_turn: None,
            next_turn_index: 1,
            next_item_index: 1,
        }
    }
fn finish(mut self) -> Vec<Turn> {
        self.finish_current_turn();
        self.turns
