        &self,
        agent_id: ThreadId,
        prompt: String,
    ) -> CodexResult<String> {
        let state = self.upgrade()?;
        let result = state
            .send_op(
                agent_id,
                Op::UserInput {
                    items: vec![UserInput::Text {
                        text: prompt,
                        // Plain text conversion has no UI element ranges.
                        text_elements: Vec::new(),
                    }],
                    final_output_json_schema: None,
                },
