                #[cfg(target_os = "macos")]
                if should_add_tmpdir {
                    if let Some(tmpdir) = dirs::home_dir() {
                        let tmp = tmpdir.join("Library/Caches/com.apple.TemporaryItems");
                        if tmp.exists() {
                            new_roots.push(tmp);
                        }
                    }
                }

                #[cfg(not(target_os = "windows"))]
                if should_add_slash_tmp {
                    if let Some(tmp) = std::env::temp_dir() {
                        new_roots.push(tmp);
                    }
                }

                new_roots
            } else {
                writable_roots
            };

            SandboxPolicyResolution {
                policy: SandboxPolicy::WorkspaceWrite {
                    writable_roots: final_writable_roots,
                    network_access,
                    exclude_tmpdir_env_var,
                    exclude_slash_tmp,
                },
                forced_auto_mode_downgraded_on_windows: false,
            }
        }
        Some(SandboxMode::DangerFullAccess) => SandboxPolicyResolution {
            policy: SandboxPolicy::DangerFullAccess,
            forced_auto_mode_downgraded_on_windows: false,
        },
        None => {
            // Default to read-only if no mode is specified
            SandboxPolicyResolution {
                policy: SandboxPolicy::new_read_only_policy(),
                forced_auto_mode_downgraded_on_windows: false,
            }
        }
    }
}
