) -> Option<WebSearchMode> {
    // 1. Check for explicit mode in ConfigToml (highest priority)
    if let Some(mode) = config_toml.web_search {
        return Some(mode);
    }

    // 2. Check for explicit mode in ConfigProfile
    if let Some(mode) = config_profile.web_search {
        return Some(mode);
    }

    // 3. Check feature flags (legacy usage)
    // If "WebSearchRequest" is enabled and no higher priority flag, enable live search
    // If "WebSearchCached" is enabled and no higher priority flag, enable cached search
    // Note: Based on Feature enum description, WebSearchCached takes precedence over WebSearchRequest.
    if features.enabled.contains(&Feature::WebSearchCached) {
        return Some(WebSearchMode::Cached);
    }
    if features.enabled.contains(&Feature::WebSearchRequest) {
        return Some(WebSearchMode::Live);
    }

    // 4. Default: return None (implies Disabled)
    None
}

