) -> Option<WebSearchMode> {
    // 1. Check explicit config in the profile first
    if let Some(mode) = config_profile.web_search {
        return Some(mode);
    }

    // 2. Check explicit config in the global TOML
    if let Some(mode) = config_toml.web_search {
        return Some(mode);
    }

    // 3. Check feature flags (higher precedence than config if both set, 
    //    but typically feature flags override default behavior)
    // According to Feature enum:
    // WebSearchCached takes precedence over WebSearchRequest.

    let has_web_search_cached = features.enabled.contains(&Feature::WebSearchCached);
    let has_web_search_live = features.enabled.contains(&Feature::WebSearchRequest);

    if has_web_search_cached {
        return Some(WebSearchMode::Cached);
    }

    if has_web_search_live {
        return Some(WebSearchMode::Live);
    }

    // 4. If neither config nor feature flags specify a mode, return None
    // The caller is responsible for applying a default if necessary.
    None
}

