async fn load_requirements_toml(
    config_requirements_toml: &mut ConfigRequirementsWithSources,
    requirements_toml_file: impl AsRef<Path>,
) -> io::Result<()> {
    let path = requirements_toml_file.as_ref();
    if !path.exists() {
        return Ok(());
    }

    let absolute_path = AbsolutePathBuf::from_absolute_path(path)?;

    let file = std::fs::File::open(&absolute_path)?;
    let reader = std::io::BufReader::new(file);
    let toml_content = toml::from_str::<ConfigRequirementsToml>(
        std::io::Read::read_to_string(reader)?
    )?;

    if let Some(policies) = &toml_content.allowed_approval_policies {
        if config_requirements_toml.allowed_approval_policies.is_none() {
            config_requirements_toml.allowed_approval_policies = Some(Sourced {
                source: RequirementSource::SystemRequirementsToml { file: absolute_path },
                value: policies.clone(),
            });
        }
    }

    if let Some(modes) = &toml_content.allowed_sandbox_modes {
        if config_requirements_toml.allowed_sandbox_modes.is_none() {
            config_requirements_toml.allowed_sandbox_modes = Some(Sourced {
                source: RequirementSource::SystemRequirementsToml { file: absolute_path },
                value: modes.clone(),
            });
        }
    }

    if let Some(servers) = &toml_content.mcp_servers {
        if config_requirements_toml.mcp_servers.is_none() {
            config_requirements_toml.mcp_servers = Some(Sourced {
                source: RequirementSource::SystemRequirementsToml { file: absolute_path },
                value: servers.clone(),
