    let guard = AbsolutePathBufGuard::new(&absolute_path);

    let content = std::fs::read_to_string(&absolute_path)?;
    let toml_value: toml::Value = content.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;

