        if let Some(sourced) = &existing.value {
            if let Some(table) = toml_value.get("mcp_servers") {
                let mut new_table = table.clone().into_table().unwrap_or_default();
                for (k, v) in &sourced.value {
                    if !new_table.contains_key(k.as_str()) {
