            func_json.insert("description".to_string(), serde_json::json!(tool.description.as_str()));

            // Convert parameters schema
            let params_schema = tool.input_schema.as_ref().map(|schema| {
                let mut schema_json = serde_json::Map::new();

                // Add required fields if present
                if let Some(req) = &schema.required {
                    schema_json.insert("required".to_string(), serde_json::json!(req.iter().map(|s| s.as_str()).collect::<Vec<_>>()));
                }

                // Add properties
                if let Some(props) = &schema.properties {
                    schema_json.insert("properties".to_string(), serde_json::json!(
                        props.iter().map(|(k, v)| (k.as_str(), v.clone())).collect::<Vec<_>>()
                    ));
                }

