            });

            func_json.insert("parameters".to_string(), params_schema.unwrap_or(serde_json::json!(serde_json::Map::new())));

            tool_json.insert("function".to_string(), serde_json::Value::Object(func_json));
        }

        tools_json.push(serde_json::Value::Object(tool_json));
