pub(crate) fn truncate_function_output_items_with_policy(
    items: &[FunctionCallOutputContentItem],
    policy: TruncationPolicy,
) -> Vec<FunctionCallOutputContentItem> {
    let mut total_bytes_used: usize = 0;
    let mut total_tokens_used: usize = 0;

    let mut result = Vec::with_capacity(items.len());
    let mut skipped_items: Vec<&FunctionCallOutputContentItem> = Vec::new();

    for item in items {
        let item_cost = match item {
            FunctionCallOutputContentItem::InputText { text } => {
                let bytes = text.len();
                let tokens = approx_token_count(text);
                (bytes as u64, tokens as u64)
            }
            FunctionCallOutputContentItem::InputImage { .. } => {
                // Images do not contribute to text truncation budget in this context
                (0, 0)
            }
        };

        let (bytes, tokens) = item_cost;
        let (budget_bytes, budget_tokens) = (policy.byte_budget(), policy.token_budget());

        if total_bytes_used + bytes <= budget_bytes && total_tokens_used + tokens <= budget_tokens {
            result.push(item.clone());
            total_bytes_used += bytes;
            total_tokens_used += tokens;
        } else {
            skipped_items.push(item);
        }
    }

    if !skipped_items.is_empty() {
        let skipped_text_items: Vec<&str> = skipped_items
            .iter()
            .filter_map(|item| match item {
                FunctionCallOutputContentItem::InputText { text } => Some(text),
                FunctionCallOutputContentItem::InputImage { .. } => None,
            })
            .collect();

        let summary = if skipped_text_items.is_empty() {
            String::from("...")
        } else {
            let joined = skipped_text_items.join(" ");
            formatted_truncate_text(&joined, policy)
        };

        let summary_item = FunctionCallOutputContentItem::InputText {
            text: summary,
        };
        result.push(summary_item);
    }

    result
}

