    use crate::ValidExec;
    use std::borrow::Cow;
    use std::ffi::OsString;
    use std::path::{Path, PathBuf};
    use path_absolutize::*;
    use std::os::unix::fs::PermissionsExt;

    // Convert relative paths to absolute using cwd if provided, otherwise error.
    fn ensure_absolute_path(path: &str, cwd: &Option<OsString>) -> Result<PathBuf> {
        let file = PathBuf::from(path);
        let result = if file.is_relative() {
            match cwd {
                Some(cwd) => file.absolutize_from(cwd),
                None => return Err(CannotCheckRelativePath { file }),
            }
        } else {
            file.absolutize()
        };
        result
            .map(Cow::into_owned)
            .map_err(|error| CannotCanonicalizePath {
                file: path.to_string(),
                error: error.kind(),
            })
    }

    fn is_executable_file(path: &str) -> bool {
        let file_path = Path::new(path);
        if let Ok(metadata) = std::fs::metadata(file_path) {
            #[cfg(unix)]
            {
                let permissions = metadata.permissions();
                return metadata.is_file() && (permissions.mode() & 0o111 != 0);
            }
            #[cfg(windows)]
            {
                return metadata.is_file();
            }
        }
        false
    }

    pub fn check(
        &self,
        valid_exec: ValidExec,
        cwd: &Option<OsString>,
        readable_folders: &[PathBuf],
        writeable_folders: &[PathBuf],
    ) -> Result<String> {
        // Validate program path
        let program_path = ensure_absolute_path(&valid_exec.program, cwd)?;
        if !is_executable_file(&valid_exec.program) {
            return Err(crate::Error::ExecutablePathNotInSystemPath {
                file: valid_exec.program,
            });
        }

        // Check system_path entries
        for sys_path in &valid_exec.system_path {
            let sys_path_buf = ensure_absolute_path(sys_path, cwd)?;
            if !is_executable_file(sys_path) {
                return Err(crate::Error::ExecutablePathNotInSystemPath {
                    file: sys_path.to_string(),
                });
            }
        }

        // Validate readable files
        for arg in &valid_exec.args {
            if let MatchedArg::Path(ref path_str) = arg.arg {
                let path_buf = ensure_absolute_path(path_str, cwd)?;
                if !path_buf.exists() {
                    continue; // Non-existent paths are allowed if they are arguments
                }

                // Check if it's a directory
                if path_buf.is_dir() {
                    if readable_folders.is_empty() {
                        return Err(ReadablePathNotInReadableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                    if !readable_folders.contains(&path_buf) {
                        return Err(ReadablePathNotInReadableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                } else if path_buf.is_file() {
                    // For files, we generally just ensure they are in readable folders if policy requires,
                    // but based on the error types provided, we focus on directories for ReadablePathNotInReadableFolders.
                    // However, if the policy expects files to be in specific folders too, we might need to check.
                    // Given the context of "folders", we primarily check directories here.
                    // If the file is in a readable folder, it's implicitly readable.
                    // We will assume the check is mainly for directories as per the error type name.
                }
            }
        }

        // Validate writeable files
        for arg in &valid_exec.args {
            if let MatchedArg::Path(ref path_str) = arg.arg {
                let path_buf = ensure_absolute_path(path_str, cwd)?;
                if !path_buf.exists() {
                    continue;
                }

                if path_buf.is_dir() {
                    if writeable_folders.is_empty() {
                        return Err(WriteablePathNotInWriteableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                    if !writeable_folders.contains(&path_buf) {
                        return Err(WriteablePathNotInWriteableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                } else if path_buf.is_file() {
                    if writeable_folders.is_empty() {
                        // If there are no writeable folders defined, any writable file is suspect unless it's in the current directory?
                        // The error type suggests we must find it in writeable_folders.
                        return Err(WriteablePathNotInWriteableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                    if !writeable_folders.contains(&path_buf) {
                        return Err(WriteablePathNotInWriteableFolders {
                            file: path_buf.to_string_lossy().to_string(),
                        });
                    }
                }
            }
        }

        // If all checks pass, return the program path as the result
        Ok(valid_exec.program)
    }
