    S: tracing::Subscriber + for<'a> LookupSpan<'a>,
{
    fn on_event(&self, event: &tracing::Event, _ctx: &tracing_subscriber::layer::Context<'_>, _values: &mut S::Value) {
        if event.target() == FEEDBACK_TAGS_TARGET {
            let mut metadata = BTreeMap::new();
            let mut visitor = FeedbackMetadataVisitor {
                metadata: &mut metadata,
            };
            event.record(&mut visitor);
            if !metadata.is_empty() {
                let _ = self.inner.add_tags(metadata);
            }
        }
    }

