    // Decrease the cursor index
    let new_cursor = self.history_cursor.unwrap() - 1;

    if new_cursor < 0 {
        // Cursor went above the start of history; reset to None (no browsing)
        self.history_cursor = None;
        return None;
    }

    let global_idx = new_cursor as usize;
    match self.populate_history_at_index(global_idx, app_event_tx) {
