    } else {
        let first_cell = self.cells.first().unwrap();
        let first_renderable = new_cells.first().unwrap();
        let needs_inset = !first_cell.is_stream_continuation();

        if needs_inset {
            let inset = InsetRenderable::new(first_renderable.clone(), Insets::tlbr(1, 0, 0, 0));
            let mut rest: Vec<Box<dyn Renderable>> = new_cells.into_iter().skip(1).collect();
            vec![Box::new(inset), rest]
        } else {
            new_cells
        }
    };

    if let Some(tail) = live_tail {
        new_renderables.push(tail);
    }

