fn apply_transcript_selection(&self, area: Rect, buf: &mut Buffer) {
    let start_point = self.transcript_selection.start();
    let end_point = self.transcript_selection.end();

    if start_point.line < end_point.line {
        let (start, end) = (start_point, end_point);
        let start_idx = start.line;
        let end_idx = end.line;

        for line_idx in start_idx..=end_idx {
            let line_meta = self.transcript_view_cache.get_meta(line_idx);
            if let Some(line_meta) = line_meta {
                let screen_y = line_meta.screen_y_offset + self.transcript_view_top;
                if screen_y < area.y {
                    continue;
                }
                if screen_y + line_meta.height > area.y + area.height {
                    continue;
                }

                let buf_y = screen_y - area.y;
                let mut buf_x = 0u16;

                if line_idx == start.line {
                    buf_x = start.column;
                }
                if line_idx == end.line {
                    buf_x = end.column;
                }

                let style = buf.line(buf_y).style();
                if !style.is_none() {
                    continue;
                }

                let mut line_content = buf.line(buf_y).content();
                let selected = if line_idx == start.line || line_idx == end.line {
                    let col_start = if line_idx == start.line { start.column } else { 0 };
                    let col_end = if line_idx == end.line { end.column } else { u16::MAX };
                    let len = col_end - col_start;
                    let segment = ratatui::text::Spans::from(
                        line_content
                            .iter()
                            .cloned()
                            .take(len as usize)
                            .collect::<Vec<_>>()
                    );
                    buf.line(buf_y).span_mut(buf_x).style(ratatui::style::Color::Reset);
                    buf.line(buf_y).span_mut(buf_x).set_style(ratatui::style::Style::default());
                    true
                } else {
                    false
                };
            }
        }
    }
