        if next_fg != fg || next_bg != bg {
            queue!(writer, SetColors(Colors::new(next_fg, next_bg)))?;
            fg = next_fg;
            bg = next_bg;
        }

        queue!(writer, Print(span.content.clone()))?;
    }

    queue!(writer, SetAttribute(crossterm::style::Attribute::Reset))
