    out: &mut TranscriptLines,
    has_emitted_lines: &mut bool,
    cell_index: usize,
    cell: &Arc<dyn HistoryCell>,
    width: u16,
    base_opts: &crate::wrapping::RtOptions<'_>,
) {
    // If no lines have been emitted yet, this is the first non-spacer content.
    // We do not insert a spacer before the very first cell content.
    if !*has_emitted_lines {
        *has_emitted_lines = true;
    } else if cell_index > 0 {
        // If lines have been emitted and this is a new cell (cell_index > 0 implies
        // we are moving to a subsequent cell in the history, as cell_index is monotonic),
        // insert a spacer row.
        let spacer_line = Line::default();
        out.lines.push(line_to_static(&spacer_line));
        out.meta.push(TranscriptLineMeta::Spacer);
        out.joiner_before.push(None);
    }

    // Prepare textwrap options specific to this cell.
    let opts = textwrap::Options::new(width as usize)
        .initial_indent(&base_opts.initial_indent)
        .subsequent_indent(&base_opts.subsequent_indent)
        .break_words(base_opts.break_words)
        .line_ending(base_opts.line_ending)
        .word_separator(&base_opts.word_separator)
