pub(crate) fn transcript_scrollbar_offset_for_mouse_event(
    scrollbar_area: Rect,
    total_lines: usize,
    viewport_lines: usize,
    top_offset: usize,
    mut event: crossterm::event::MouseEvent,
    interaction: &mut ScrollBarInteraction,
    clamp_to_track: bool,
