    /// For wheel-like streams we also apply a minimum of ±1 line for any non-zero input so wheel
    /// notches never become "dead" due to rounding or mis-detection.
    fn flush_lines_at(
        last_redraw_at: &mut Instant,
        carry_lines: f32,
        now: Instant,
        stream: &mut ScrollStream,
    ) -> i32 {
